    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "De tre situationer er korrekte i substans. Svaret udelader dog kvalifikationen 'i særlige tilfælde' og gør punkterne til en opremsning af tilfælde, hvor UDK 'kan' indhente. Det ændrer retsvirkningen: Det fremstår, som om de tre situationer i sig selv er tilstrækkelige. Punkt 2 gengiver desuden den ofte forældede dokumentation som en betingelse ('og der foreligger forældet dokumentation'). Det er en af rubrikkens væsentlige fejl, og kilden siger 'ofte'."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret dækker de tre kritiske situationer. Det første kritiske element, 'i særlige tilfælde', mangler dog. Svaret siger kun 'kan ... i følgende tilfælde'. Svaret nævner heller ikke, at dokumentationen 'ofte' er forældet og ikke beskriver den aktuelle tilstand."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvornår UDK kan indhente en aktuel redegørelse, og nævner de tre situationer fra vejledningen."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lov, bekendtgørelse eller vejledningsafsnit."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer 'og der foreligger forældet dokumentation' som en betingelse for forlængelsessituationen. Kilden siger, at der 'ofte' foreligger forældet dokumentation, så betingelsen har ikke støtte. Ellers er indholdet hentet fra vejledningen."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Begge påkrævede kvalifikationer er tabt. 'I særlige tilfælde' er udeladt. 'Ofte forældet' er blevet til en fast betingelse."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Opremsningen er intern konsistent, og den afsluttende sætning om formålet med redegørelsen hænger sammen med de tre situationer."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "'Kan' er bevaret. Fraværet af 'i særlige tilfælde' og omdannelsen af 'ofte forældet' til en betingelse gør beføjelsen bredere og mere mekanisk end kilden, så modaliteten gengives ikke præcist."
    }
  },
  "xhaile_coverage": {
    "A69": {
      "label": "yes",
      "reason": "Punkt 1 gengiver journaloplysninger, der indikerer funktionstab uden beskrivelse af funktionsniveau og påvirkning."
    },
    "A70": {
      "label": "partial",
      "reason": "Svaret dækker forlængelse af et tidsbegrænset tillæg og forældet dokumentation. Det gør forældelsen til en betingelse i stedet for en hyppig situation ('ofte'), og det nævner ikke, at dokumentationen ikke beskriver den aktuelle tilstand."
    },
    "A71": {
      "label": "yes",
      "reason": "Punkt 3 gengiver påbegyndt behandlingsforløb ved ansøgningstidspunktet samt begrænsede lægelige oplysninger."
    }
  },
  "overall_notes": "Svaret gengiver de tre situationer fra vejledning 5.1.3.1 korrekt, men udelader 'i særlige tilfælde' og omdanner 'ofte forældet dokumentation' til en betingelse. Det er to af rubrikkens påkrævede kvalifikationer. Svaret angiver heller ingen kilde, så C04 er not_met og C05 og C06 er not_assessable."
}

